def call_openai_server_single_prompt(
    prompt, model="gpt-3.5-turbo", max_decode_steps=20, temperature=0.8
):
  try:
    completion = openai.ChatCompletion.create(
        model=model,
        temperature=temperature,
        max_tokens=max_decode_steps,
        messages=[
            {"role": "user", "content": prompt},
        ],
    )
    return completion.choices[0].message.content
  except openai.error.Timeout as e:
    retry_time = e.retry_after if hasattr(e, "retry_after") else 30
    print(f"Timeout error occurred. Retrying in {retry_time} seconds...")
    time.sleep(retry_time)
    return call_openai_server_single_prompt(
        prompt, max_decode_steps=max_decode_steps, temperature=temperature
    )
  except openai.error.RateLimitError as e:
    retry_time = e.retry_after if hasattr(e, "retry_after") else 30
    print(f"Rate limit exceeded. Retrying in {retry_time} seconds...")
    time.sleep(retry_time)
    return call_openai_server_single_prompt(
        prompt, max_decode_steps=max_decode_steps, temperature=temperature
    )
  except openai.error.APIError as e:
    retry_time = e.retry_after if hasattr(e, "retry_after") else 30
    print(f"API error occurred. Retrying in {retry_time} seconds...")
    time.sleep(retry_time)
    return call_openai_server_single_prompt(
        prompt, max_decode_steps=max_decode_steps, temperature=temperature
    )
  except openai.error.APIConnectionError as e:
    retry_time = e.retry_after if hasattr(e, "retry_after") else 30
    print(f"API connection error occurred. Retrying in {retry_time} seconds...")
    time.sleep(retry_time)
    return call_openai_server_single_prompt(
        prompt, max_decode_steps=max_decode_steps, temperature=temperature
    )
  except openai.error.ServiceUnavailableError as e:
    retry_time = e.retry_after if hasattr(e, "retry_after") else 30
    print(f"Service unavailable. Retrying in {retry_time} seconds...")
    time.sleep(retry_time)
    return call_openai_server_single_prompt(
        prompt, max_decode_steps=max_decode_steps, temperature=temperature
    )
  except OSError as e:
    retry_time = 5
    print(
        f"Connection error occurred: {e}. Retrying in {retry_time} seconds..."
    )
    time.sleep(retry_time)
    return call_openai_server_single_prompt(
        prompt, max_decode_steps=max_decode_steps, temperature=temperature
    )
def call_openai_server_func(
    inputs, model="gpt-3.5-turbo", max_decode_steps=20, temperature=0.8
):
  if isinstance(inputs, str):
    inputs = [inputs]
  outputs = []
  for input_str in inputs:
    output = call_openai_server_single_prompt(
        input_str,
        model=model,
        max_decode_steps=max_decode_steps,
        temperature=temperature,
    )
    outputs.append(output)
  return outputs
def call_palm_server_from_cloud(
    input_text, model="text-bison-001", max_decode_steps=20, temperature=0.8
):
  assert isinstance(input_text, str)
  assert model == "text-bison-001"
  all_model_names = [
      m
      for m in palm.list_models()
      if "generateText" in m.supported_generation_methods
  ]
  model_name = all_model_names[0].name
  try:
    completion = palm.generate_text(
        model=model_name,
        prompt=input_text,
        temperature=temperature,
        max_output_tokens=max_decode_steps,
    )
    output_text = completion.result
    return [output_text]
  except:
    retry_time = 10
    print(f"Retrying in {retry_time} seconds...")
    time.sleep(retry_time)
    return call_palm_server_from_cloud(
        input_text, max_decode_steps=max_decode_steps, temperature=temperature
    )
BOOLEAN_SYMBOLS = [["false", "true"], ["no", "yes"], ["invalid", "valid"]]
all_lowercase_letters = string.ascii_lowercase
bracketed_lowercase_letters_set = set(
    [f"({l})" for l in all_lowercase_letters]
)
bracketed_uppercase_letters_set = set(
    [f"({l.upper()})" for l in all_lowercase_letters]
)
def read_jsonl(filepath):
  with open(filepath, "r", encoding="utf-8") as fh:
    return [json.loads(line) for line in fh.readlines() if line]
def remove_punctuation_from_string(input_string, is_filename=True):
  if is_filename:
    punctuation_subset_str = (
        string.punctuation.replace("!", "").replace("?", "").replace(".", "")
    )
    output_string = input_string.translate(
        str.maketrans("", "", punctuation_subset_str)
    )
    output_string = (
        output_string.replace("!", "<EXCLAMATION>")
        .replace("?", "<QUESTION>")
        .replace(".", "<PERIOD>")
    )
  else:
    output_string = input_string.translate(
        str.maketrans("", "", string.punctuation)
    )
  return output_string
def instruction_to_filename(instruction, md5_hashing=True):
  import hashlib
  if md5_hashing:
    m = hashlib.md5()
    m.update(instruction.encode("ascii"))
    filename = m.hexdigest()
  else:
    filename = instruction.replace("\n", "")
    filename = remove_punctuation_from_string(repr(filename))
    filename = filename if filename else "<NO INSTRUCTION>"
  return filename
def polish_sentence(sentence, add_ending_punc=False):
  sentence = sentence.strip()
  if sentence:
    sentence = sentence.replace("**", "")
    if len(sentence) > 1:
      sentence = (
          sentence[0].upper() + sentence[1:]
      )
    if add_ending_punc and not (
        sentence.endswith(".")
        or sentence.endswith("?")
        or sentence.endswith("!")
    ):
      sentence += "."
  return sentence
def _split_by_Q(sentence):
  return sentence.split("Q:")[0].strip()
def _format_mmlu_example(data, idx, include_question=True):
  choices = ["(A)", "(B)", "(C)", "(D)"]
  prompt = data.iloc[idx, 0]
  k = data.shape[1] - 2
  for j in range(k):
    prompt += "\n{} {}".format(choices[j], data.iloc[idx, j + 1])
  if include_question:
    prompt += "\nWhat's the answer in (A) (B) (C) (D)?"
  return prompt
def _format_aqua_example(data, idx, include_question=True):
  question = data[idx]["question"]
  options = ["(" + item for item in data[idx]["options"]]
  for item in options:
    question += f"\n{item}"
  if include_question:
    question += "\nWhat's the answer in (A) (B) (C) (D) (E)?"
  return question
def gen_prompt(
    data,
    instruction,
    idx,
    include_qa=True,
    instruction_pos="Q_begin",
    dataset_name="mmlu",
):
  dataset_name = dataset_name.lower()
  assert dataset_name in {
      "mmlu",
      "bbh",
      "gsm8k",
      "multiarith",
      "aqua",
  }, (
      "The lower-case dataset name must be one of mmlu, bbh, gsm8k, multiarith,"
      " or aqua."
  )
  assert instruction_pos in {
      "before_Q",
      "Q_begin",
      "Q_end",
      "A_begin",
  }, (
      "The instruction position should be either before the question, or at the"
      " beginning of the question, at the end of the question, or at the"
      " beginning of the answer."
  )
  if dataset_name == "mmlu":
    question = _format_mmlu_example(data, idx)
  elif dataset_name == "bbh":
    question = data[idx]["input"]
  elif dataset_name == "gsm8k":
    question = data.iloc[idx, 0]
  elif dataset_name == "multiarith":
    question = data[idx]["sQuestion"].strip()
  else:
    assert dataset_name == "aqua"
    question = _format_aqua_example(data, idx)
  prompt = ""
  if include_qa:
    if instruction_pos == "before_Q":
      if instruction:
        prompt += instruction + "\n"
      prompt += "Q: " + question
      prompt += "\n\nA:"
    elif instruction_pos == "Q_begin":
      if instruction:
        prompt += "Q: " + instruction + "\n"
      else:
        prompt += "Q: "
      prompt += question
      prompt += "\n\nA:"
    elif instruction_pos == "Q_end":
      prompt += "Q: " + question
      if instruction:
        prompt += "\n" + instruction + "\n\nA:"
      else:
        prompt += "\n\nA:"
    else:
      assert instruction_pos == "A_begin"
      prompt += f"Q: {question}\n\n"
      prompt += "A:"
      if instruction:
        prompt += f" {instruction}"
  else:
    assert instruction_pos in {"Q_begin", "Q_end"}
    if instruction_pos == "Q_begin":
      if instruction:
        prompt += instruction + "\n"
      prompt += question
    else:
      assert instruction_pos == "Q_end"
      prompt += question
      if instruction:
        prompt += "\n" + instruction
  return prompt
def fetch_true_answer(data, idx, dataset_name):
  dataset_name = dataset_name.lower()
  assert dataset_name in {
      "mmlu",
      "bbh",
      "gsm8k",
      "multiarith",
      "aqua",
  }, (
      "The lower-case dataset name must be one of mmlu, bbh, gsm8k, multiarith,"
      " or aqua."
  )
  if dataset_name == "mmlu":
    return data.iloc[idx, -1]
  elif dataset_name == "bbh":
    return data[idx]["target"]
  elif dataset_name == "gsm8k":
    return data.iloc[idx, 1]
  elif dataset_name == "multiarith":
    return int(data[idx]["lSolutions"][0])
  else:
    assert dataset_name == "aqua"
    return data[idx]["correct"]
def _get_index_from_symbol(answer):
  answer = str(answer).lower()
  if answer in bracketed_lowercase_letters_set:
    answer = re.findall(r"\(.*?\)", answer)[0][1]
  index = ord(answer) - ord("a")
  return index
def _get_answer_text(input_text, answer_symbol):
  re_split_string = (
      "".join([rf"\({l.upper()}\)|" for l in all_lowercase_letters]) + "A:"
  )
  choice_text_list = [
      item.strip().lower() for item in re.split(re_split_string, input_text)
  ][1:]
  choice_text_list = [
      re.split("\n", item)[0] for item in choice_text_list
  ]
  answer_text = choice_text_list[_get_index_from_symbol(answer_symbol)]
  return answer_text
def _prompting_to_get_raw_answers(
    prompts,
    call_server_func,
    server_index=1,
    max_retry=1,
    sleep_time=60,
    verbose=False,
):
  outputs = []
  for i in range(int(max_retry + 1)):
    if i > 0:
      if verbose:
        print(
            f"retry {i}/{max_retry} after sleeping for {sleep_time:.0f} seconds"
        )
      time.sleep(sleep_time)
    try:
      outputs = call_server_func(prompts, server_index=server_index)
    except:
      continue
    break
  assert (
      outputs
  ), "No prompting output after all retries, indicating possible server outage."
  return outputs
def _get_accuracy(
    true_answer, pred_answer, input_text="", treat_include_as_correct=False
):
  true_answer = str(true_answer).lower()
  pred_answer = str(pred_answer).lower()
  true_answer_included_in_pred_answer = true_answer in pred_answer
  if input_text:
    if true_answer in all_lowercase_letters:
      true_answer = f"({true_answer})"
    if pred_answer in all_lowercase_letters:
      pred_answer = f"({pred_answer})"
    if true_answer not in bracketed_lowercase_letters_set:
      return 0
    true_answer_text = _get_answer_text(
        input_text=input_text, answer_symbol=true_answer
    ).lower()
    all_symbols_raw = np.unique(re.findall(r"\([A-Z]\)", input_text))
    all_symbols = []
    for item in sorted(list(bracketed_uppercase_letters_set)):
      if item in all_symbols_raw:
        all_symbols.append(item)
      else:
        break
    other_answer_texts_list = []
    for symbol in all_symbols:
      if _get_index_from_symbol(symbol) != _get_index_from_symbol(true_answer):
        other_answer_texts_list.append(
            _get_answer_text(input_text=input_text, answer_symbol=symbol)
        )
  else:
    other_answer_texts_list = []
    true_answer_text = ""
  if true_answer in bracketed_lowercase_letters_set:
    true_answer = re.findall(r"\(.*?\)", true_answer)[0][1]
  if pred_answer in bracketed_lowercase_letters_set:
    pred_answer = re.findall(r"\(.*?\)", pred_answer)[0][1]
  result_exact_match = (pred_answer == true_answer) or (
      remove_punctuation_from_string(pred_answer, is_filename=False).strip()
      == remove_punctuation_from_string(true_answer, is_filename=False).strip()
  )
  is_choice_text_exact_match = bool(input_text) and (
      pred_answer == true_answer_text
      or remove_punctuation_from_string(pred_answer).strip() == true_answer_text
  )
  def _text_in_list_not_in_target(text_list, target):
    return all([item not in target for item in text_list])
  def _target_not_in_any_of_text_list(target, text_list):
    return all([target not in text for text in text_list])
  is_true_choice_text_included_and_other_choice_text_excluded = (
      bool(input_text)
      and true_answer_text in pred_answer
      and (
          _text_in_list_not_in_target(
              other_answer_texts_list, pred_answer.replace(true_answer_text, "")
          )
          if _target_not_in_any_of_text_list(
              true_answer_text, other_answer_texts_list
          )
          else _text_in_list_not_in_target(other_answer_texts_list, pred_answer)
      )
  )
  is_boolean_match = False
  if any([true_answer in item for item in BOOLEAN_SYMBOLS]):
    boolean_type_index = np.where(
        [true_answer in item for item in BOOLEAN_SYMBOLS]
    )[0][0]
    true_answer_as_true_or_false_str = str(
        bool(
            np.where(
                np.array(BOOLEAN_SYMBOLS[boolean_type_index]) == true_answer
            )[0][0]
        )
    ).lower()
    if pred_answer in {"0", "1"}:
      pred_answer = str(bool(int(pred_answer))).lower()
    is_boolean_match = (
        pred_answer == true_answer_as_true_or_false_str
        or pred_answer.strip() == true_answer_as_true_or_false_str.strip()
    )
  accuracy = int(
      result_exact_match
      or is_choice_text_exact_match
      or is_true_choice_text_included_and_other_choice_text_excluded
      or is_boolean_match
  )
  if treat_include_as_correct:
    accuracy = int(bool(accuracy) or true_answer_included_in_pred_answer)
  return accuracy
def get_accuracy_of_list(
    true_answer,
    pred_answer_list,
    input_text="",
    treat_include_as_correct=False,
):
  assert not isinstance(true_answer, list)
  accuracy_list = list(
      map(
          lambda x: _get_accuracy(
              true_answer=true_answer,
              pred_answer=x,
              input_text=input_text,
              treat_include_as_correct=treat_include_as_correct,
          ),
          pred_answer_list,
      )
  )
  return np.average(accuracy_list)
class MockMetrics:
    def get_normalized_prediction(prediction, treat_as_number, num_decimals, treat_as_bool):
        prediction_parsed = prediction.lower().strip()
        if treat_as_number:
            try:
                num_match = re.search(r'(\d+(\.\d+)?)', prediction_parsed[::-1])
                if num_match:
                    num_str = num_match.group(1)[::-1]
                    return f"{round(float(num_str), num_decimals):.{num_decimals}f}"
            except ValueError:
                pass
        if treat_as_bool:
            if prediction_parsed in ['true', 'yes', 'valid', '1']: return 'true'
            if prediction_parsed in ['false', 'no', 'invalid', '0']: return 'false'
        return prediction_parsed
metrics = MockMetrics()
def evaluate_single_instruction(
    data,
    instruction,
    eval_index_all,
    batch_size,
    call_server_func,
    dataset_name,
    num_servers,
    extract_final_answer_by_prompting_again,
    instruction_pos,
    is_multiple_choice,
    include_qa=True,
    evaluate_in_parallel=True,
    num_decodes=1,
    max_retry=5,
    sleep_time=60,
    prediction_treat_as_number=False,
    prediction_treat_as_bool=False,
    prediction_num_decimals=0,
    is_gpt_model=False,
    verbose=False,
):
  assert prediction_treat_as_number == "adaptive" or isinstance(
      prediction_treat_as_number, bool
  )
  assert instruction_pos in {
      "before_Q",
      "Q_begin",
      "Q_end",
      "A_begin",
  }, (
      "The instruction position should be either before the question, or at the"
      " beginning of the question, at the end of the question, or at the"
      " beginning of the answer."
  )
  num_eval_examples = len(eval_index_all)
  assert type(is_multiple_choice) in {bool, list}, (
      "is_multiple_choice must be a Boolean variable or a list of Boolean"
      " variables"
  )
  if isinstance(is_multiple_choice, bool):
    is_multiple_choice = [is_multiple_choice] * num_eval_examples
  else:
    assert (
        len(is_multiple_choice) == num_eval_examples
    ), "is_multiple_choice must have the same length as eval_index_all"
  true_answers = [
      fetch_true_answer(data, idx=idx, dataset_name=dataset_name)
      for idx in eval_index_all
  ]
  raw_prompts_flattened = []
  for i in range(num_eval_examples):
    raw_prompt = gen_prompt(
        data,
        instruction=instruction,
        idx=eval_index_all[i],
        include_qa=include_qa,
        instruction_pos=instruction_pos,
        dataset_name=dataset_name,
    )
    raw_prompts_flattened.append(raw_prompt)
  class DummyPool:
      def __init__(self, num_servers): self.num_servers = num_servers
      def apply_async(self, func, args):
          class DummyResult:
              def get(self): return func(*args)
          return DummyResult()
      def close(self): pass
      def join(self): pass
  mp = type('module', (object,), {'Pool': DummyPool})()
  if evaluate_in_parallel:
    def _prompt_a_list_in_parallel(
        raw_prompts_flattened,
        num_servers,
        call_server_local_func,
    ):
      num_examples = len(raw_prompts_flattened)
      raw_prompts_grouped_by_batch_size = []
      raw_prompts_single_batch = []
      i = 0
      while i < num_examples:
        raw_prompt = raw_prompts_flattened[i]
        raw_prompts_single_batch.append(raw_prompt)
        i += 1
        if i % batch_size == 0:
          raw_prompts_grouped_by_batch_size.append(raw_prompts_single_batch)
          raw_prompts_single_batch = []
      if raw_prompts_single_batch:
        raw_prompts_grouped_by_batch_size.append(raw_prompts_single_batch)
      server_indices = [
          i % num_servers + 1
          for i in range(len(raw_prompts_grouped_by_batch_size))
      ]
      p1 = mp.Pool(num_servers)
      r = [
          p1.apply_async(
              _prompting_to_get_raw_answers,
              args=[
                  raw_prompts_single_batch,
                  call_server_local_func,
                  server_index,
                  max_retry,
                  sleep_time,
                  verbose,
              ],
          )
          for raw_prompts_single_batch, server_index in list(
              zip(raw_prompts_grouped_by_batch_size, server_indices)
          )
      ]
      p1.close()
      p1.join()
      raw_answers = []
      for i in range(len(raw_prompts_grouped_by_batch_size)):
        raw_answers += r[i].get()[:batch_size]
      return raw_answers
    raw_answers = _prompt_a_list_in_parallel(
        raw_prompts_flattened=raw_prompts_flattened,
        num_servers=num_servers,
        call_server_local_func=call_server_func,
    )
  else:
    raw_answers = []
    for prompt in raw_prompts_flattened:
        result = call_server_func(prompt)
        if isinstance(result, list):
            raw_answers.append(result[0])
        else:
            raw_answers.append(result)
  if verbose:
    print("first round of prompting finished")
  if extract_final_answer_by_prompting_again:
    raw_prompts_flattened_second_round = list(
        map(
            lambda a, b: a + " " + _split_by_Q(b),
            raw_prompts_flattened,
            raw_answers,
        )
    )
    raw_prompts_flattened_second_round = [
        item + " " + "So the final answer is"
        for item in raw_prompts_flattened_second_round
    ]
    if evaluate_in_parallel:
      raw_answers_second_round = _prompt_a_list_in_parallel(
          raw_prompts_flattened=raw_prompts_flattened_second_round,
          num_servers=num_servers,
          call_server_local_func=functools.partial(
              call_server_func, max_decode_steps=50
          ),
      )
    else:
      raw_answers_second_round = [
          call_server_func(prompt, max_decode_steps=50)[0]
          for prompt in raw_prompts_flattened_second_round
      ]
    if verbose:
      print("second round of prompting finished")
  if verbose:
    print(
        "extracting final prediction with"
        f" treat_as_number={prediction_treat_as_number},"
        f" treat_as_bool={prediction_treat_as_bool}, and"
        f" num_decimals={prediction_num_decimals}"
    )
  def _extract_second_round_answer_for_parsing(ans):
    return ans.strip(":").strip().split("\n")[0].split("Q:")[0]
  raw_answers_to_parse = (
      list(
          map(
              _extract_second_round_answer_for_parsing, raw_answers_second_round
          )
      )
      if extract_final_answer_by_prompting_again
      else raw_answers
  )
  if prediction_treat_as_number == "adaptive":
    true_answer_is_numeric = [isinstance(item, (int, float)) or (isinstance(item, str) and item.isnumeric()) for item in true_answers]
    prediction_treat_as_number_list = true_answer_is_numeric.copy()
  else:
    assert isinstance(prediction_treat_as_number, bool)
    prediction_treat_as_number_list = [prediction_treat_as_number] * len(
        true_answers
    )
  def _parse_prediction(
      x, is_gpt_model, treat_as_number, num_decimals, treat_as_bool
  ):
    if is_gpt_model and r"\boxed" in x:
      return re.findall(r"\\boxed{(.*?)}", x)[0]
    else:
      return metrics.get_normalized_prediction(
          x,
          treat_as_number=treat_as_number,
          num_decimals=num_decimals,
          treat_as_bool=treat_as_bool,
      )
  choices = list(
      map(
          lambda x, y: _parse_prediction(
              x,
              is_gpt_model,
              y,
              prediction_num_decimals,
              prediction_treat_as_bool,
          ),
          raw_answers_to_parse,
          prediction_treat_as_number_list,
      )
  )
  if not extract_final_answer_by_prompting_again:
    choices = [
        _extract_second_round_answer_for_parsing(item) for item in choices
    ]
  accuracies = []
  for i, _ in enumerate(eval_index_all):
    treat_include_as_correct = not prediction_treat_as_number_list[i]
    input_text = raw_prompts_flattened[i] if is_multiple_choice[i] else ""
    accuracy = get_accuracy_of_list(
        true_answer=true_answers[i],
        pred_answer_list=choices[
            int(num_decodes * i) : int(num_decodes * (i + 1))
        ],
        input_text=input_text,
        treat_include_as_correct=treat_include_as_correct,
    )
    accuracies.append(accuracy)
  detailed_results_df = pd.DataFrame(
      list(
          zip(
              eval_index_all,
              raw_prompts_flattened,
              raw_answers,
              choices,
              true_answers,
              accuracies,
          )
      ),
      columns=[
          "index_in_raw_dataset",
          "raw_prompt",
          "raw_answer",
          "parsed_answer",
          "true_answer",
          "accuracy",
      ],
  )
  if extract_final_answer_by_prompting_again:
    detailed_results_df.insert(
        3, "raw_prompt_second_round", raw_prompts_flattened_second_round
    )
    detailed_results_df.insert(
        4, "raw_answer_second_round", raw_answers_second_round
    )
  detailed_results_df.set_index("index_in_raw_dataset", inplace=True)
  return detailed_results_df
def load_bbh_task_data(
    task_name: str,
    base_dir: str,
    qa_format: bool = True,
):
  import os
  files = os.listdir(base_dir)
  task_names = [f.split(".json")[0] for f in files]
  task_names = [f for f in task_names if "." not in f]
  if task_name not in task_names:
    raise ValueError(
        f"Task {task_name} not a valid bbh task.  Consult `get_task_names()`"
        " for a list of valid tasks."
    )
  task_loc = f"{base_dir}/{task_name}.json"
  with open(task_loc, "r") as f:
    data = json.loads(f.readlines()[0])["examples"]
  if qa_format:
    formatted_examples = []
    for d in data:
      formatted_examples.append(
          {"input": f"{d['input']}", "target": f"{d['target']}"}
      )
    data = formatted_examples
  return data
def extract_string_in_square_brackets(input_string):
  raw_result = re.findall(r"\[.*?\]", input_string)
  if raw_result:
    return raw_result[0][1:-1]
  else:
    return ""
def parse_tag_content(text, prefix="<TEXT>", suffix="</TEXT>"):
  pattern = f"{prefix}(.*?){suffix}"
  results = re.findall(pattern, text, re.DOTALL)
  return results
def _bucketize_float(num, n_buckets=20):
  assert num >= 0 and num <= 1, "The given number must be between 0 and 1."
  return round(num * n_buckets)
def gen_ins_and_score_pairs_substr(
    old_instructions_and_scores,
    old_instruction_score_threshold=0.1,
    max_num_instructions=1000,
    return_str_only=False,
    num_score_buckets=np.inf,
):
  assert num_score_buckets == np.inf or isinstance(num_score_buckets, int)
  old_instructions_and_scores_str = ""
  old_instructions_and_scores = sorted(
      old_instructions_and_scores, key=lambda x: x[1]
  )[-max_num_instructions:]
  old_instructions_and_scores_in_meta_prompt = []
  for instruction, score, i_step in old_instructions_and_scores:
    if (
        not old_instruction_score_threshold
        or score >= old_instruction_score_threshold
    ):
      old_instructions_and_scores_in_meta_prompt.append(
          (instruction, score, i_step)
      )
      if num_score_buckets == np.inf:
        score_to_show = round(score, 3)
      else:
        score_to_show = _bucketize_float(score, num_score_buckets)
      old_instructions_and_scores_str += (
          f"\ntext:\n{instruction}\nscore:\n{score_to_show}\n"
      )
  if return_str_only:
    return old_instructions_and_scores_str
  else:
    return (
        old_instructions_and_scores_str,
        old_instructions_and_scores_in_meta_prompt,
    )
def gen_meta_prompt(
    old_instructions_and_scores,
    instruction_pos,
    optimizer_llm_name,
    old_instruction_score_threshold=0.1,
    max_num_instructions=1000,
    meta_prompt_type="both_instructions_and_exemplars",
    few_shot_qa_pairs=False,
    include_qa=True,
    data=None,
    few_shot_index_list=None,
    instructions_before_exemplars=True,
    num_score_buckets=np.inf,
    dataset_name="",
    task_name="",
):
  assert instruction_pos in {
      "before_Q",
      "Q_begin",
      "Q_end",
      "A_begin",
  }, (
      "The instruction position should be either before the question, or at the"
      " beginning of the question, at the end of the question, or at the"
      " beginning of the answer."
  )
  assert meta_prompt_type in {
      "both_instructions_and_exemplars",
      "instructions_only",
  }
  assert dataset_name in {
      "mmlu",
      "bbh",
      "gsm8k",
  }, "The lower-case dataset name must be one of mmlu, bbh, gsm8k."
  assert num_score_buckets == np.inf or isinstance(num_score_buckets, int)
  meta_prompt = ""
  if meta_prompt_type == "both_instructions_and_exemplars":
    if optimizer_llm_name.lower() in {"gpt-3.5-turbo", "gpt-4"}:
      if instruction_pos == "A_begin":
        meta_prompt_old_instruction_part = (
            "Your task is to generate the answer starting sentence <Start>."
            " Below are some previous starting sentences with their scores."
            " The score ranges from 0 to 100.\n"
        )
      else:
        meta_prompt_old_instruction_part = (
            "Your task is to generate the instruction <INS>."
            " Below are some previous instructions with their scores."
            " The score ranges from 0 to 100.\n"
        )
    else:
      assert optimizer_llm_name.lower() == "text-bison"
      meta_prompt_old_instruction_part = (
          "I have some texts along with their corresponding scores."
          " The texts are arranged in ascending order based on their scores,"
          " where higher scores indicate better quality.\n\n"
      )
    old_instructions_and_scores_str = gen_ins_and_score_pairs_substr(
        old_instructions_and_scores=old_instructions_and_scores,
        old_instruction_score_threshold=old_instruction_score_threshold,
        max_num_instructions=max_num_instructions,
        return_str_only=True,
        num_score_buckets=num_score_buckets,
    )
    meta_prompt_old_instruction_part += old_instructions_and_scores_str
    meta_prompt_exemplar_part = ""
    if few_shot_qa_pairs:
      if optimizer_llm_name.lower() in {"gpt-3.5-turbo", "gpt-4"}:
        meta_prompt_exemplar_part += "Below are some problems.\n"
      else:
        assert optimizer_llm_name.lower() == "text-bison"
        meta_prompt_exemplar_part += (
            "The following exemplars show how to apply your text: you replace"
            " <INS> in each input with your text, then read the input and give"
            " an output. We say your output is wrong if your output is"
            " different from the given output, and we say your output is"
            " correct if they are the same. When replacing <INS> with an old"
            " piece of text above, we get wrong outputs on the following"
            " inputs.\n\n"
        )
      for idx in few_shot_index_list:
        if dataset_name == "mmlu":
          question = _format_mmlu_example(data, idx)
          true_answer = data.iloc[idx, -1]
        elif dataset_name == "bbh":
          question = data[idx]["input"]
          true_answer = data[idx]["target"]
        else:
          assert dataset_name == "gsm8k"
          question = data.iloc[idx, 0]
          true_answer = data.iloc[idx, 1]
        if include_qa:
          if instruction_pos == "before_Q":
            meta_prompt_exemplar_part += f"\ninput:\n<INS>\nQ: {question}\nA:"
          elif instruction_pos == "Q_begin":
            meta_prompt_exemplar_part += f"\ninput:\nQ: <INS>\n{question}\nA:"
          elif instruction_pos == "Q_end":
            meta_prompt_exemplar_part += f"\ninput:\nQ: {question}\n<INS>\nA:"
          else:
            assert instruction_pos == "A_begin"
            if optimizer_llm_name.lower() in {"gpt-3.5-turbo", "gpt-4"}:
              meta_prompt_exemplar_part += f"\nQ: {question}\nA: <Start>"
            else:
              assert optimizer_llm_name.lower() == "text-bison"
              meta_prompt_exemplar_part += f"\ninput:\nQ: {question}\nA: <INS>"
        else:
          assert instruction_pos in {"Q_begin", "Q_end"}
          if optimizer_llm_name.lower() in {"gpt-3.5-turbo", "gpt-4"}:
            if instruction_pos == "Q_begin":
              meta_prompt_exemplar_part += f"\nProblem:\n<INS>\n{question}\n"
            elif instruction_pos == "Q_end":
              meta_prompt_exemplar_part += f"\nProblem:\n{question}\n<INS>\n"
          else:
            assert optimizer_llm_name.lower() == "text-bison"
            if instruction_pos == "Q_begin":
              meta_prompt_exemplar_part += f"\ninput:\n<INS>\n{question}\n"
            elif instruction_pos == "Q_end":
              meta_prompt_exemplar_part += f"\ninput:\n{question}\n<INS>\n"
        if optimizer_llm_name.lower() in {"gpt-3.5-turbo", "gpt-4"}:
          meta_prompt_exemplar_part += (
              f"\nGround truth answer:\n{true_answer}\n"
          )
        else:
          assert optimizer_llm_name.lower() == "text-bison"
          meta_prompt_exemplar_part += f"\noutput:\n{true_answer}\n"
    if few_shot_qa_pairs:
      if instructions_before_exemplars:
        meta_prompt += (
            meta_prompt_old_instruction_part
            + "\n\n"
            + meta_prompt_exemplar_part
        )
      else:
        meta_prompt += (
            meta_prompt_exemplar_part
            + "\n\n"
            + meta_prompt_old_instruction_part
        )
    else:
      meta_prompt += meta_prompt_old_instruction_part
    if optimizer_llm_name.lower() in {"gpt-3.5-turbo", "gpt-4"}:
      if instruction_pos == "A_begin":
        meta_prompt += (
            "\n\nGenerate a starting sentence that is different from all the"
            " <Start> sentences above, and has a higher score than all the"
            " <Start> sentences above. The starting sentence should begin with"
            " <Start> and end with </Start>. The starting sentence should be"
            " concise, effective, and generally applicable to all QA pairs"
            " above."
        )
      else:
        meta_prompt += (
            "\n\nGenerate an instruction that"
            " is different from all the instructions <INS> above,"
            " and has a higher score than all the instructions <INS> above."
            " The instruction should begin with <INS> and end with </INS>."
            " The instruction should be concise, effective,"
            " and generally applicable to all problems above."
        )
    else:
      assert optimizer_llm_name.lower() == "text-bison"
      meta_prompt += (
          "\n\nWrite your new text that is different from the old ones and"
          " has a score as high as possible. Write the text in square brackets."
      )
  else:
    assert meta_prompt_type == "instructions_only"
    assert instruction_pos in {"Q_begin", "Q_end", "A_begin"}
    if instruction_pos == "Q_begin":
      instruction_pos_description = "at the beginning of the question"
    elif instruction_pos == "Q_end":
      instruction_pos_description = "at the end of the question"
    else:
      assert instruction_pos == "A_begin"
      instruction_pos_description = "at the beginning of the answer"
    if dataset_name == "gsm8k":
      instruction_task_description = "grade school math"
    elif dataset_name == "mmlu":
      instruction_task_description = task_name
    else:
      assert dataset_name == "bbh"
      instruction_task_description = " ".join(task_name.split("_"))
    meta_instruction = (
        f"Create a piece of text {instruction_pos_description.strip()} to"
        " enhance the precision in solving diverse"
        f" {instruction_task_description.strip()} problems."
    )
    old_instructions_and_scores = sorted(
        old_instructions_and_scores, key=lambda x: x[1]
    )
    old_instructions_and_scores_str = ""
    for instruction, score, _ in old_instructions_and_scores:
      if num_score_buckets == np.inf:
        score_to_show = round(score, 2)
      else:
        score_to_show = _bucketize_float(score, num_score_buckets)
      old_instructions_and_scores_str += (
          f"\n\nPrecision: {score_to_show} <TEXT>{instruction}</TEXT>"
      )
    meta_prompt += meta_instruction + old_instructions_and_scores_str
  return meta_prompt
def run_evolution(**kwargs):
  num_search_steps = kwargs["num_search_steps"]
  old_instruction_score_threshold = kwargs["old_instruction_score_threshold"]
  scorer_llm_dict = kwargs["scorer_llm_dict"]
  optimizer_llm_dict = kwargs["optimizer_llm_dict"]
  extract_final_answer_by_prompting_again = kwargs[
